      "session": 1,
      "subject": "law",
      "sourceId": "law-01",
      "number": 24,
      "stem": "A 上市公司(下稱 A 公司)近年營收不佳，業績大幅滑落，董事長甲乃與財務經理乙、會計師丙串通，美化 A 公司財務報表。A 公司其他董事丁戊己庚均因疏忽未察覺財務報表之數字有問題，投資人因而受有損害。請問關於證券交易法上財務報表不實的民事損害賠償責任，何人可以主張比例責任？",
      "options": [
        "A 公司",
        "董事長甲",
        "會計師乙",
        "董事丁"
      ],
