      "number": 13,
      "stem": "張三個性積極外向，勇於投資各項高風險之金融商品，他積極進出臺灣股票市場，購買風險相對較高之高科技股票，另為了避險或追求更高的利潤，張三亦進入期貨市場，買賣期貨與選擇權。依張三所使用之投資工具，可判定其風險偏好特性：",
