      "stem": "有關元大臺灣 50ETF 之敘述如下： I、一年配息 1 次。 II、其標的是根據臺灣證券交易所上市且市值前 50 名的股票編製而成的市值加權股價指數。 III、透過實物申購與買回的機制，使市價貼近淨值。 IV、臺灣 50 指數已成為期交所指數期貨與選擇權的標的。試問上述敘述中正確者為？",
