      "number": 16,
      "stem": "一檔美式價內權證發行，代碼為 071726 ，發行價格為每單位新臺幣 1.134 元，履約價格為新臺幣 37.00 元，行使比例為1：0.250，即每一單位認購權證可買進標的證券 0. 250 股， Delta 約為 0.5，存續期間六個月，槓桿效果為 8.20 倍。根據上述所提供的資訊，判斷下列敘述何者正確： I、該檔權證為國內標的之認購權證 II、發行日前一營業日標的證券收盤價為 38.00 元 III、發行時該檔權證的實質槓桿約為 4.1 倍 IV、該權證發行日時溢價比為 11.66",
