      "number": 17,
      "stem": "岳不群發現最近股市有關比特幣概念股的股票特別會漲，於是以融資的方式買進 5 張與此概念股有高度相關的上市公司股票，經過他努力分析發現，該檔股票預期報酬率高達 30%，報酬標準差僅有 40%，而目前規定融資可以 6 成，在不考慮券商手續費、證券交易稅與融資利息成本之下，試問岳不群投資組合的期望報酬率與風險分別是多少？",
