      "stem": "請問目前市場上對於 VR(虛擬實境)很看好，所以投資人對於宏達電股價看多，如果當你也認同時，請問以下幾種方式，可以讓你獲利？ I、買入宏達電買權 II、買入宏達電賣權 III、賣出宏達電買權 IV、賣出宏達電賣權",
