        "公司法第六章之一所稱之關係企業及其董事、監察人與經理人者，除能證明不具控制、聯合控制或重大影響者外，應視為實質關係人，於財務報告附註揭露有關資訊",
        "與發行人受同一總管理處管轄之公司或機構及其董事、監察人與經理人，除能證明不具控制、聯合控制或重大影響者外，應視為實質關係人，於財務報告附註揭露有關資訊",
        "單一關係人交易金額或餘額達發行人各該項交易總額或餘額百分之五以上者，皆應按關係人名稱單獨列示"
