        "無需考慮是否誤導使用者之判斷，應公告說明該錯誤及原發布之資訊並不適合使用，並儘速重新公告修正後之預測資訊",
        "應先考慮是否誤導使用者之判斷，如無誤導之可能性時，則僅公告說明該錯誤及原發布之資訊已不適合使用即可，而無須重新公告修正後之預測資訊",
