      "stem": "甲公司成立於 2015 年初，近年存貨成本的資料如下：2015 年底成本$302,000，淨變現價值 $290,000；2016 年底成本$386,000，淨變現價值$380,000；2017 年底成本$356,000，淨變現價值$358,000。另假設甲公司以備抵存貨跌價損失科目記錄期末存貨之評價結果，則2017 年底存貨評價之會計處理應認列多少備抵存貨跌價損失？",
