      "stem": "捷克公司於X1 年度發生下列事項：(1)指撥$30,000 之保留盈餘另作他用、(2)轉回已指撥之保留盈餘$40,000、(3)宣告$50,000 之現金股利、(4)支付$30,000 之應付股利、(5)本期淨利為$50,000。上列變動對X1 年保留盈餘帳戶餘額之影響為何？",
