        "或有負債發生的情況之一為：因過去事件所產生之可能義務，且其存在與否繫於一個以上不確定未來事件之發生或不發生來證實，而該不確定未來事件係不能完全由該企業控制",
        "或有負債發生的情況之一為：因過去事件所產生之現時義務，但未符合負債準備認列條件（非很有可能流出具經濟效益之資源或金額無法可靠估計）而未予以認列",
